DB::run('DELETE FROM git_sync_jobs');DB::run('INSERT IGNORE INTO git_sync_state(connection_id) VALUES(?)',[$tbConnection]);
GitJob::enqueue($tbConnection,'pipelines','repository',['page'=>1]);$gmJob=GitJob::claim();
check($gmJob!==null && $gmJob['kind']==='pipelines','file Git réserve une tâche avec un propriétaire');
