$gmLink=TicketBranch::link($tbTicket,$tbC,$tbEvent,$uid);
$gmRaw=['number'=>101,'title'=>'Suivi de livraison','state'=>'open','updated_at'=>'2026-11-03T00:00:00Z','head'=>['ref'=>$tbName,'sha'=>str_repeat('5',40),'repo'=>['full_name'=>$tbC['repository']]],'base'=>['ref'=>'staging','sha'=>str_repeat('6',40)],'merge_commit_sha'=>str_repeat('7',40),'mergeable'=>false];
