$gmMeta=$gmPR['metadata'];$gmMeta['merge_check']=['revision'=>GitPullRequest::revision($gmPR),'conflict'=>true,'checked_at'=>gmdate('Y-m-d H:i:s')];DB::run('UPDATE development_events SET metadata_json=? WHERE id=?',[json_encode($gmMeta,JSON_THROW_ON_ERROR),$gmPrId]);
