check(DevelopmentRunPayload::conflict('github',['mergeable'=>null])===null && DevelopmentRunPayload::conflict('github',['mergeable'=>true])===false,'calcul de fusion inconnu distinct de sans conflit');
check(DevelopmentRunPayload::conflict('github',['mergeable'=>false,'mergeable_state'=>'blocked'])===null,'politique de fusion bloquée non interprétée comme conflit de code');
try {DevelopmentRunPayload::object('github','check',['id'=>42,'head_sha'=>str_repeat('4',40)],$tbC['repository'],['sha'=>str_repeat('5',40)]);check(false,'contrôle du commit demandé');} catch(InvalidArgumentException) {check(true,'contrôle reçu pour un autre commit refusé');}
try {DevelopmentRunPayload::object('github','status',['sha'=>str_repeat('5',40),'state'=>'success'],$tbC['repository']);check(false,'identité du contrôle');} catch(InvalidArgumentException) {check(true,'statut sans contexte stable refusé');}
check(DevelopmentRunPayload::conflict('bitbucket',['values'=>[['type'=>'git_mergeability_check','status'=>'FAILED','reason'=>'conflicts']]])===true,'conflit Bitbucket établi par son contrôle Git');
check(DevelopmentRunPayload::conflict('bitbucket',['values'=>[['type'=>'git_mergeability_check','reason'=>'merge_impossible']]])===null,'autre blocage de fusion non interprété comme conflit de code');
$gmWorkflow=DevelopmentRunPayload::object('github','workflow',['id'=>55,'name'=>'Tests PHP','head_sha'=>str_repeat('5',40),'head_branch'=>$tbName,'status'=>'completed','conclusion'=>'failure','updated_at'=>'2026-11-03T00:01:00Z','run_attempt'=>2,'html_url'=>'https://github.com/sample/branches/actions/runs/55'],$tbC['repository']);$gmBuildId=DevelopmentEvent::save($tbC,$gmWorkflow,false);
check(DB::one('SELECT 1 FROM development_event_tickets WHERE event_id=? AND ticket_id=?',[$gmBuildId,$tbTicket])!==null && $gmWorkflow['state']==='failure','résultat de tests en échec associé au commit exact du ticket');
$gmOldAttempt=$gmWorkflow;$gmOldAttempt['metadata']['attempt']=1;$gmOldAttempt['state']='success';$gmOldAttempt['occurred_at']='2099-01-01 00:00:00';DevelopmentEvent::save($tbC,$gmOldAttempt,false);check(DB::one('SELECT state FROM development_events WHERE id=?',[$gmBuildId])['state']==='failure','ancienne tentative retardée ne remplace pas la nouvelle');
$gmUnknown=DevelopmentRunPayload::object('github','workflow',['id'=>56,'head_sha'=>str_repeat('5',40),'status'=>'completed'],$tbC['repository']);check($gmUnknown['state']==='unknown','exécution terminée sans résultat ne devient pas verte');
$gmBB=DevelopmentRunPayload::object('bitbucket','deployment',['uuid'=>'{123-abc}','environment'=>['name'=>'Production'],'release'=>['commit'=>['hash'=>str_repeat('7',40)],'created_on'=>'2026-11-03T00:02:00Z'],'state'=>['name'=>'COMPLETED','status'=>['name'=>'SUCCESSFUL'],'completion_date'=>'2026-11-03T00:03:00Z']],$tbC['repository']);check($gmBB['state']==='success' && $gmBB['metadata']['environment']==='Production','déploiement Bitbucket confirmé par son résultat et son environnement');
$gmBBPending=DevelopmentRunPayload::object('bitbucket','deployment',['uuid'=>'{124-abc}','release'=>['commit'=>['hash'=>str_repeat('7',40)]],'state'=>['name'=>'IN_PROGRESS','status'=>['name'=>'']]],$tbC['repository']);check($gmBBPending['state']==='running','déploiement Bitbucket en cours sans résultat final reste en cours');
$gmDeploy=DevelopmentRunPayload::object('github','deployment',['id'=>90,'environment'=>'staging','sha'=>str_repeat('8',40),'ref'=>'staging','created_at'=>'2026-11-03T00:01:00Z'],$tbC['repository'],['state'=>'success','updated_at'=>'2026-11-03T00:04:00Z']);$gmDepId=DevelopmentEvent::save($tbC,$gmDeploy,false);
check(DB::one('SELECT 1 FROM development_event_tickets WHERE event_id=? AND ticket_id=?',[$gmDepId,$tbTicket])===null,'fusion ou nom staging seul ne prouve pas la livraison de ce ticket');
$gmPR['state']='merged';DevelopmentEvent::save($tbC,$gmPR,false);DevelopmentEvent::deploymentProof($tbC,$gmDepId,$gmPrId,str_repeat('7',40),str_repeat('8',40));
check(DB::one('SELECT 1 FROM development_event_tickets WHERE event_id=? AND ticket_id=?',[$gmDepId,$tbTicket])!==null,'preuve de présence du commit de fusion relie le déploiement au ticket');
DevelopmentEvent::save($tbC,$gmDeploy,false);check(DB::one('SELECT 1 FROM development_event_tickets WHERE event_id=? AND ticket_id=?',[$gmDepId,$tbTicket])!==null,'preuve de livraison conservée après actualisation du déploiement');
$gmBefore=App\Models\Ticket::find($tbTicket)['version'];DevelopmentEvent::save($tbC,$gmWorkflow,false);check(App\Models\Ticket::find($tbTicket)['version']===$gmBefore,'observation Git ne modifie pas les champs du ticket');
DB::run('UPDATE git_sync_state SET enabled=0 WHERE connection_id=?',[$tbConnection]);GitJob::enqueue($tbConnection,'checks','example',['sha'=>str_repeat('5',40)]);check(GitJob::claim()===null,'dépôt désactivé ne démarre pas de travail automatique');
DB::run('DELETE FROM git_sync_jobs');DB::run('UPDATE git_sync_state SET enabled=1 WHERE connection_id=?',[$tbConnection]);GitSync::request($tbConnection);$gmPending=GitJob::status($tbConnection);check(($gmPending['counts']['pending']??0)>=3,'rattrapage programme séparément PR pipelines et déploiements');
