GitJob::enqueue($tbConnection,'repository','repository',['page'=>1,'through'=>'2026-10-01 00:00:00']);$gmWatermark=GitJob::claim();GitJob::finish($gmWatermark,['page'=>2,'through'=>'2026-10-01 00:00:00']);check(DB::one('SELECT repository_watermark FROM git_sync_state WHERE connection_id=?',[$tbConnection])['repository_watermark']===null,'page intermédiaire ne déplace pas le point de rattrapage');
$gmWatermark=GitJob::claim();GitJob::finish($gmWatermark);check(DB::one('SELECT repository_watermark FROM git_sync_state WHERE connection_id=?',[$tbConnection])['repository_watermark']==='2026-10-01 00:00:00','rattrapage terminé enregistre sa borne initiale');
